public class StringArrayDeserializer_createContextual_TriageGen0Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
    }

    @Test
    public void testCreateContextual_AllPaths_NullDeser() throws Exception {
        // Case 1: deser is null, findContextualValueDeserializer returns null -> returns this
        StringArrayDeserializer spyDeser = spy(new StringArrayDeserializer());
        doReturn(null).when(spyDeser).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.findContextualValueDeserializer(any(), eq(property))).thenReturn(null);

        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        assertEquals(spyDeser, result);
    }








}

package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_createContextual_TriageGen0Test {

    private StringArrayDeserializer deserializer;
    private DeserializationContext ctxt;
    private BeanProperty property;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
    }









    @Test
    public void testCreateContextual_AllPaths_SameDeserializer() throws Exception {
        // Case 5: deser found, not default, but it's the same as _elementDeserializer
        // Since _elementDeserializer is private, we simulate this by making the spy return itself 
        // from findConvertingContentDeserializer
        StringArrayDeserializer spyDeser = spy(new StringArrayDeserializer());

        // We need to force _elementDeserializer to be the mockDeser. 
        // Since we can't set private fields easily without reflection, 
        // we use a trick: if findConverting returns the same object as the existing _elementDeserializer,
        // but _elementDeserializer is null in a new instance... 
        // Actually, the only way to have _elementDeserializer != null is to have a non-default instance.
        // We'll use reflection to set the field to ensure we hit the `_elementDeserializer != deser` check.

        java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        JsonDeserializer<?> mockDeser = mock(JsonDeserializer.class);
        field.set(spyDeser, mockDeser);

        doReturn(mockDeser).when(spyDeser).findConvertingContentDeserializer(any(), any(), any());
        doReturn(false).when(spyDeser).isDefaultDeserializer(mockDeser);

        JsonDeserializer<?> result = spyDeser.createContextual(ctxt, property);
        assertEquals(spyDeser, result);
    }
}
